def _nest_join_data(
    data: dict[str, Any], join_definitions: list[JoinConfig]
) -> dict[str, Any]:
    nested_data: dict = {}
    for key, value in data.items():
        nested = False
        for join in join_definitions:
            # Determine the nesting key: use join_prefix if provided, otherwise use model's table name or alias
            if join.join_prefix:
                if key.startswith(join.join_prefix):
                    nested_key = join.join_prefix.rstrip("_")
                    nested_field = key[len(join.join_prefix) :]
                    if nested_key not in nested_data:
                        nested_data[nested_key] = {}
                    nested_data[nested_key][nested_field] = value
                    nested = True
                    break
            else:
                # When no prefix is provided, nest under the model's table name or alias
                model_name = join.alias.name if join.alias else join.model.__tablename__
                if key.startswith(model_name + "_"):
                    nested_field = key[len(model_name) + 1 :]  # Remove model_name + "_"
                    if model_name not in nested_data:
                        nested_data[model_name] = {}
                    nested_data[model_name][nested_field] = value
                    nested = True
                    break
                # Also handle exact matches (when no prefix and direct column access)
                elif key == join.model.__tablename__ or (join.alias and key == join.alias.name):
                    # This case handles when the joined model's primary key or direct reference is included
                    if model_name not in nested_data:
                        nested_data[model_name] = {}
                    nested_data[model_name][key] = value
                    nested = True
                    break
        if not nested:
            nested_data[key] = value
    return nested_data
